from agents import Agent
from config import OPENAI_MODEL
from tools import get_incident_details,get_service_health,search_service_logs,search_incident_knowledge_base,execute_simulated_remediation
triage_specialist=Agent(name='Triage Specialist',model=OPENAI_MODEL,instructions='Use incident details and service health to identify service, severity, impact and facts needed for diagnosis. Do not remediate.',tools=[get_incident_details,get_service_health])
diagnosis_specialist=Agent(name='Diagnosis Specialist',model=OPENAI_MODEL,instructions='Use service health, logs and KB evidence. State likely cause, evidence, confidence and alternatives. Do not execute actions.',tools=[get_service_health,search_service_logs,search_incident_knowledge_base])
remediation_specialist=Agent(name='Remediation Specialist',model=OPENAI_MODEL,instructions='Recommend the safest reversible supported remediation using KB evidence. State verification. Never execute.',tools=[search_incident_knowledge_base])
incident_commander=Agent(name='Incident Commander',model=OPENAI_MODEL,instructions='Coordinate incident response. For a new incident call triage_incident, diagnose_incident, then propose_remediation. Never execute unless the user CURRENT instruction contains exact token APPROVED_BY_USER. With approval, call execute_simulated_remediation using that exact token, then get_service_health to verify. Never claim execution unless tool status is EXECUTED. Structure output: Incident, Evidence, Diagnosis, Recommended action, Approval status, Execution result, Verification.',tools=[triage_specialist.as_tool(tool_name='triage_incident',tool_description='Triage incident using details and health.'),diagnosis_specialist.as_tool(tool_name='diagnose_incident',tool_description='Investigate logs, health and KB evidence.'),remediation_specialist.as_tool(tool_name='propose_remediation',tool_description='Recommend safest supported remediation and verification.'),execute_simulated_remediation,get_service_health])
